type"]="item",["id"]=12207,["name"]="Riesenei",["quantity"]=65,["icon"]="inv_egg_03"},{["type"]="item",["id"]=3713,["name"]="Feine Gewürze",["quantity"]=130,["icon"]="inv_misc_food_wheat_02"}}},{["from"]=275,["to"]=300,["recipe"]={["type"]="spell",["id"]=18244,["name"]="Gedünsteter Sonnenschuppenlachs",["icon"]="inv_misc_fish_19"},["crafts"]=35,["materials"]={{["type"]="item",["id"]=13760,["name"]="Roher Sonnenschuppenlachs",["quantity"]=35,["icon"]="inv_misc_fish_19"}}}},["notes"]={{["skill"]=1,["text"]="Rezepte ohne gesonderten Hinweis beim passenden Berufs- bzw. Verbandlehrer lernen. Händlerrezepte können ausverkauft sein. Ausbildungs-, Rezept- und Werkzeugkosten sind nicht Teil der Materialliste."},{["skill"]=50,["text"]="Gesellenkochen beim Lehrer lernen, ab Charakterstufe 10. Das erhöht das Skill-Limit von 75 auf 150."},{["skill"]=125,["text"]="Expertenkochbuch bei Shandrina im Eschental (Allianz) oder Wulan in Schattenflucht, Desolace (Horde); ab Charakterstufe 20."},{["skill"]=130,["text"]="Seltsam schmeckendes Omelett: Rezept bei Kendor Kabonka in Sturmwind oder Keena im Arathihochland."},{["skill"]=175,["text"]="Gerösteter Raptor: Rezept bei Hammon Karwn oder Keena im Arathihochland."},{["skill"]=225,["text"]="Fachmann durch „Muschelette Surprise“ bei Dirge Quikcleave in Gadgetzan: Charakterstufe 35, Kochen 225, 12 Rieseneier, 10 scharfes Muschelfleisch und 20 Alteraclochkäse. Questmaterial zusätzlich einplanen."},{["skill"]=225,["text"]="Monsteromelett: Rezept bei Himmik in Winterquell oder Malygen/Bale im Teufelswald."},{["skill"]=275,["text"]="Gedünsteter Sonnenschuppenlachs: Rezept bei Gikkix im Hafen von Steamwheedle, Tanaris."}},["source"]="https://www.wow-professions.com/classic/cooking-leveling-guide-classic-wow"},{["id"]="first-aid",["name"]="Erste Hilfe",["icon"]="🩹",["aliases"]="erste hilfe verband verbände verbaende first aid",["kind"]="craft",["partner"]="Kein Partnerberuf nötig",["intro"]="Sekundärberuf: belegt keinen Hauptberufsplatz. Stoffe