to"]=210,["recipe"]={["type"]="spell",["id"]=7929,["name"]="Schwerer Seidenverband",["englishName"]="Heavy Silk Bandage",["icon"]="inv_misc_bandage_02"},["crafts"]=50,["materials"]={{["type"]="item",["id"]=4306,["name"]="Seidenstoff",["quantity"]=100,["englishName"]="Silk Cloth",["icon"]="inv_fabric_silk_01"}}},{["from"]=210,["to"]=225,["recipe"]={["type"]="spell",["id"]=10840,["name"]="Magiestoffverband",["englishName"]="Mageweave Bandage",["icon"]="inv_misc_bandage_19"},["crafts"]=30,["materials"]={{["type"]="item",["id"]=4338,["name"]="Magiestoff",["quantity"]=30,["englishName"]="Mageweave Cloth",["icon"]="inv_fabric_mageweave_01"}}},{["from"]=225,["to"]=240,["recipe"]={["type"]="spell",["id"]=10840,["name"]="Magiestoffverband",["englishName"]="Mageweave Bandage",["icon"]="inv_misc_bandage_19"},["crafts"]=30,["materials"]={{["type"]="item",["id"]=4338,["name"]="Magiestoff",["quantity"]=30,["englishName"]="Mageweave Cloth",["icon"]="inv_fabric_mageweave_01"}}},{["from"]=240,["to"]=260,["recipe"]={["type"]="spell",["id"]=10841,["name"]="Schwerer Magiestoffverband",["englishName"]="Heavy Mageweave Bandage",["icon"]="inv_misc_bandage_20"},["crafts"]=30,["materials"]={{["type"]="item",["id"]=4338,["name"]="Magiestoff",["quantity"]=60,["englishName"]="Mageweave Cloth",["icon"]="inv_fabric_mageweave_01"}}},{["from"]=260,["to"]=290,["recipe"]={["type"]="spell",["id"]=18629,["name"]="Runenstoffverband",["englishName"]="Runecloth Bandage",["icon"]="inv_misc_bandage_11"},["crafts"]=50,["materials"]={{["type"]="item",["id"]=14047,["name"]="Runenstoff",["quantity"]=50,["englishName"]="Runecloth",["icon"]="inv_fabric_purplefire_01"}}},{["from"]=290,["to"]=300,["recipe"]={["type"]="spell",["id"]=18630,["name"]="Schwerer Runenstoffverband",["englishName"]="Heavy Runecloth Bandage",["icon"]="inv_misc_bandage_12"},["crafts"]=15,["materials"]={{["type"]="item",["id"]=14047,["name"]="Runenstoff",["quantity"]=30,["englishName"]="Runecloth",["icon"]="inv_fabric_purplefire_01"}}}},["notes"]={{["skill"]=1,["text"]="Rezepte ohne gesonderten Hinweis beim passenden Berufs- bzw. Verbandlehrer lernen. Händlerrezepte können ausverkauft sein. Ausbildungs-, Rezept- und Werkzeugkosten sind nicht Teil der Materialliste."},{["skill"]=50,["text"]="Gesellenausbildung beim Erste-Hilfe-Lehrer lernen, bevor du das Skill-Limit 75 erreichst."},{["skill"]=125,["text"]="Expertenbuch bei Deneb Walker in Stromgarde (Allianz) oder Balai Lok’Wein im Brackenwall, Düstermarschen (Horde). Auch die Handbücher für schwere Seidenverbände und Magiestoffverbände kaufen."},{["skill"]=180,["text"]="Handbuch für schwere Seidenverbände benutzen; ab 210 das Handbuch für Magiestoffverbände."},{["skill"]=225,["text"]="Fachmann durch Triage, ab Charakterstufe 35 und Erste Hilfe 225: Doktor Gustaf VanHowzen in Theramore oder Doktor Gregory Victor in Hammerfall. Die Questverbände verwenden und kritisch Verletzte zuerst versorgen."},{["skill"]=240,["text"]="Schwere Magiestoffverbände beim Triage-Arzt lernen; bei 260 Runenstoffverbände und bei 290 schwere Runenstoffverbände."}},["source"]="https://www.wow-professions.com/classic/first-aid-leveling-guide-classic-wow"},{["id"]="herbalism",["name"]="Kräuterkunde",["icon"]="🌿",["aliases"]="kräuter kraeuter kräutern herb herbalism",["kind"]="gather",["partner"]="Alchemie",["intro"]="Kräutersuche aktivieren. Wähle Gebiete passend zu deinem Charakterlevel; höherwertige Kräuter erst ab der angegebenen Mindestfertigkeit sammeln.",["steps"]={{["from"]=1,["to"]=70,["title"]="Friedensblume, Silberblatt, Erdwurzel",["text"]="Startgebiete: Wald von Elwynn, Dun Morogh, Teldrassil, Durotar, Mulgore oder Tirisfal."},{["from"]=70,["to"]=115,["title"]="Maguskönigskraut und Wilddornrose; Würgetang ab 85",["text"]="Brachland, Silberwald, Loch Modan oder Dunkelküste."},{["from"]=115,["to"]=170,["title"]="Wildstahlblume; Königsblut ab 125, Lebenswurz ab 150",["text"]="Vorgebirge des Hügellands, Sumpfland oder Steinkrallengebirge."},{["from"]=170,["to"]=205,["title"]="Golddorn und Blassblatt; Khadgars Schnurrbart ab 185",["text"]="Schlingendorntal oder Arathihochland."},{["from"]=205,["to"]=230,["title"]="Lila Lotus und Feuerblüte",["text"]="Tanaris oder Sengende Schlucht."},{["from"]=230,["to"]=270,["title"]="Sonnengras; Geisterpilz ab 245",["text"]="Hinterland. Höhlen nur mit passendem Charakterlevel betreten."},{["from"]=270,["to"]=300,["title"]="Gromsblut, Goldener Sansam, Traumblatt und spätere Kräuter",["text"]="Teufelswald. Kräuter nach der angezeigten Sammelbarkeit auswählen."}},["notes"]={{["skill"]=50,["text"]="Geselle vor dem Skill-Limit 75 lernen; Experte vor 150 und Fachmann vor 225. Bei Sammelberufen sind die Lehrerregeln nicht mit den Herstellungsberufen gleichzusetzen."}},["source"]="https://www.wow-professions.com/classic/herbalism-leveling-guide-classic-wow"},{["id"]="mining",["name"]="Bergbau",["icon"]="⛏️",["aliases"]="bergbau mining erz erze abbauen",["kind"]="gather",["partner"]="Schmiedekunst oder Ingenieurskunst",["intro"]="Bergbauhacke im Inventar und Mineralsuche aktiv halten. Die Gebiete sind Vorschläge, keine garantierten Vorkommen.",["steps"]={{["from"]=1,["to"]=65,["title"]="Kupfer",["text"]="Startgebiete wie Durotar, Mulgore, Wald von Elwynn oder Dun Morogh."},{["from"]=65,["to"]=125,["title"]="Zinn, Kupfer und Silber ab 75",["text"]="Vorgebirge des Hügellands, Rotkammgebirge, Eschental oder Brachland."},{["from"]=125,["to"]=175,["title"]="Eisen und Gold ab 155",["text"]="Arathihochland, Desolace oder Tausend Nadeln."},{["from"]=175,["to"]=245,["title"]="Mithril; Echtsilber ab 230",["text"]="Hinterland oder Tanaris."},{["from"]=245,["to"]=275,["title"]="Kleine Thoriumvorkommen",["text"]="Krater von Un’Goro, Teufelswald oder Verwüstete Lande."},{["from"]=275,["to"]=300,["title"]="Auch reiche Thoriumvorkommen",["text"]="Winterquell, Östliche Pestländer, Brennende Steppe oder Un’Goro."}},["notes"]={{["skill"]=50,["text"]="Geselle vor dem Skill-Limit 75 lernen; Experte vor 150 und Fachmann vor 225. Bei Sammelberufen sind die Lehrerregeln nicht mit den Herstellungsberufen gleichzusetzen."}},["source"]="https://www.wow-professions.com/classic/mining-leveling-guide-classic-wow"},{["id"]="skinning",["name"]="Kürschnerei",["icon"]="🐾",["aliases"]="kürschner kuerschner kürschnerei kuerschnerei skinning leder balg",["kind"]="gather",["partner"]="Lederverarbeitung",["intro"]="Kürschnermesser im Inventar behalten. Tote Wildtiere vollständig plündern, dann kürschnern. Auch orange Ziele garantieren keinen Skillpunkt.",["steps"]={{["from"]=1,["to"]=75,["title"]="Wildtiere im Startgebiet",["text"]="Zum Beispiel Durotar oder Dun Morogh; die ganz frühen Startgegner lassen sich nicht alle kürschnern."},{["from"]=75,["to"]=155,["title"]="Wildtiere auf dem Weg ins nächste Gebiet",["text"]="Brachland oder Loch Modan und Sumpfland. Passende, noch skillgebende Tiere wählen."},{["from"]=155,["to"]=205,["title"]="Raptoren und andere Wildtiere",["text"]="Arathihochland; für die Horde auch Tausend Nadeln ab etwa 165."},{["from"]=205,["to"]=260,["title"]="Wildtiere und Yetis",["text"]="Feralas: zunächst um Camp Mojache, später höherstufige Yetis."},{["from"]=260,["to"]=300,["title"]="Höherstufige Wildtiere",["text"]="Feralas; ab etwa 280 auch Un’Goro. Bei Gegnern ab Stufe 20 benötigt man grundsätzlich Gegnerstufe × 5 Kürschnerei."}},["notes"]={{["skill"]=50,["text"]="Geselle vor dem Skill-Limit 75 lernen; Experte vor 150 und Fachmann vor 225. Bei Sammelberufen sind die Lehrerregeln nicht mit den Herstellungsberufen gleichzusetzen."}},["source"]="https://www.wow-professions.com/classic/skinning-leveling-guide-classic-wow"},{["id"]="fishing",["name"]="Angeln",["icon"]="🎣",["aliases"]="angeln fishing fischen fisch angel",["kind"]="gather",["partner"]="Kochen",["intro"]="Sekundärberuf. Angel ausrüsten und Köder verwenden. Skillpunkte entstehen durch erfolgreiche Fänge; der benötigte Fangumfang steigt. Es gibt keine feste Material- oder Fangzahl bis 300.",["steps"]={{["from"]=1,["to"]=75,["title"]="Angel und einfache Köder kaufen",["text"]="In einem Gewässer eines Startgebiets angeln."},{["from"]=75,["to"]=150,["title"]="Gesellenrang lernen",["text"]="In geeigneten Gewässern einer Hauptstadt weiterangeln; entkommende Fische durch Köder reduzieren."},{["from"]=150,["to"]=225,["title"]="Expertenbuch benutzen",["text"]="Buch bei Old Man Heming in Beutebucht, ab Charakterstufe 20. Mit Ködern beispielsweise in den Düstermarschen angeln."},{["from"]=225,["to"]=300,["title"]="Nat Pagles Ausbildungsquest abschließen",["text"]="Ab Charakterstufe 35 und Angeln 225 bei Nat Pagle in den Düstermarschen. Danach mit Ködern etwa in Feralas, Tanaris oder im Hinterland weiterangeln."}},["notes"]={{["skill"]=225,["text"]="Für Nat Pagle werden vier Questfische benötigt: Feralas-Ahi in Feralas, Nebelschilf-Mahi-Mahi in den Sümpfen des Elends, Sar’theris-Barsch in Desolace und Blausegelstrandflossenfisch an der Wilden Küste im Schlingendorntal. Erst nach Annahme der Quest fangen."}},["source"]="https://www.wow-professions.com/classic/fishing-leveling-guide-classic-wow"}}
